'use strict';
const $=s=>document.querySelector(s),screen=$('#screen'),overlay=$('#overlay'),sheet=$('#sheet');
const paths={positions:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M4 10h16M10 10v10"/>',orders:'<path d="M8 5h12M8 12h12M8 19h12M4 5h.01M4 12h.01M4 19h.01"/>',control:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 015 0c0 2-2.5 2-2.5 4M12 17h.01"/>',reduce:'<path d="M5 8h14M8 5L5 8l3 3M19 16H5m11-3l3 3-3 3"/>',tighten:'<path d="M12 3l8 4v5c0 5-8 9-8 9s-8-4-8-9V7l8-4zM8 12h8M12 8v8"/>',tp:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M16 8l5-5M17 3h4v4"/>',cancel:'<circle cx="12" cy="12" r="8"/><path d="M8 8l8 8M16 8l-8 8"/>',close:'<path d="M10 5H5v14h5M10 12h11m-4-4l4 4-4 4"/>',pause:'<path d="M8 5v14M16 5v14"/>',back:'<path d="M15 5l-7 7 7 7"/>',check:'<path d="M5 12l4 4L19 6"/>',chevron:'<path d="M9 5l7 7-7 7"/>'};
const icon=(k)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.help}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const qty=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:4}),price=n=>Number(n).toFixed(4);
let scenario='before',page='positions',view='home',selected='reduce',lastFocus=null,submitted=false;
let position,globalEntry,strategies,request=null;
const guides={
 reduce:{title:'想降低仓位',sub:'少承担一些，也继续参与',button:'减仓',icon:'reduce',lead:'退出一部分，余下仓位继续由系统管理。',example:'100 XRP 的空仓，减仓 50% 后剩余 50 XRP。原自动 TP1 数量单撤销，目标价仍保留；之后达到该条件，才按原规则申请余仓保本。已兑现的亏损不会被余仓保本追回。'},
 tighten:{title:'想缩小回撤',sub:'保留仓位，收紧退出边界',button:'收紧止损',icon:'tighten',lead:'仓位不变，把允许的回撤空间缩小。',example:'这笔空仓的止损从 2.0800 收紧到 2.0400。更小的反弹就可能触发退出；即使之后趋势延续，也不会自动补回仓位。'},
 tp:{title:'想在目标价兑现',sub:'指定价格和退出数量',button:'设置 / 修改止盈',icon:'tp',lead:'设定一个价格，退出你指定的数量。',example:'设置 1.8400 退出 25 XRP。普通限价单可能部分成交；完整成交后，如果还有余仓，按原阶段继续管理。原有失败或时间退出仍可能先结束交易。'},
 cancel:{title:'想撤掉人工目标',sub:'保留保护，取消获利限价单',button:'取消人工止盈',icon:'cancel',lead:'撤销自己设置的止盈计划，继续保留必要保护。',example:'撤销 1.8000 的人工止盈后，该价格不再按原计划自动兑现。当前止损保留，原策略失败或时间退出仍有效；旧自动 TP1 不会重新挂回。'},
 close:{title:'想结束这一笔',sub:'退出全部余仓',button:'单笔全平',icon:'close',lead:'以市价退出这笔余仓，再完成残单清理和结算。',example:'这张 XRP 卡片的全平只结束这笔交易，其他持仓不变。策略新开仓开关仍保持原值，未来新的合格信号仍可能开仓。'},
 pause:{title:'暂时不想开新仓',sub:'已有持仓继续管理',button:'暂停新开仓',icon:'pause',lead:'暂停后续入场，让已有自动仓位继续保护与退出。',example:'全局暂停后，所有策略都不能新增入场，但各策略原来的启用选择保留。只想暂停 SOR-1H 时，也可以单独关闭该策略。'}
};
function resetState(){position={qty:100,entry:2,current:scenario==='runner'?1.82:1.92,stop:scenario==='runner'?1.88:2.08,profit:scenario==='manual'?'manual':'automatic',tp:scenario==='manual'?{price:1.8,qty:30}:null};globalEntry=true;strategies={'SOR-1H-001':true,'BRF2-001':true};request=null;submitted=false;}
function nav(){const active=['home','guide','detail'].includes(view)?page:'positions';$('#nav').innerHTML=Object.entries({positions:'持仓',orders:'委托',control:'主控'}).map(([k,label])=>`<button data-act="nav" data-id="${k}" class="${active===k?'active':''}" ${submitted?'disabled':''}>${icon(k)}${label}</button>`).join('');}
function stateName(){return scenario==='runner'?'Runner 追踪中':position.tp?'人工止盈中':position.profit==='condition'?'等待原目标价':position.profit==='cancelled'?'自动保护中':'TP1 前';}
function managementCaption(){return scenario==='runner'?'当前余仓继续自动追踪':position.tp?`人工止盈 ${price(position.tp.price)} · ${qty(position.tp.qty)} XRP`:position.profit==='condition'?'管理转换目标 1.8800':position.profit==='cancelled'?'人工止盈已取消 · 保留自动保护':'原 TP1 目标 1.8800';}
function row(label,value,cls=''){return `<div class="outcome-row"><span class="muted">${label}</span><b class="${cls}">${value}</b></div>`;}
function renderHome(){view='home';nav();
 if(page==='positions'){
  screen.innerHTML=`<div class="titlebar"><h2>持仓<span class="count">${position.qty?1:0}</span></h2><button class="help-link" data-act="guide">${icon('help')}操作帮助</button></div><div class="auto-strip"><i class="live-dot"></i>${globalEntry?'系统自动运行':'新开仓已暂停'}<span>模拟数据</span></div>`+(position.qty?`<article class="position"><div class="row"><div><span class="symbol">XRP<small>USDT</small></span><span class="side">空</span></div><span class="auto-tag"><i class="live-dot"></i>自动管理</span></div><div class="tags"><span class="tag">SOR-1H</span><span class="tag">5× · 全仓</span><span class="tag">${stateName()}</span></div><div class="pnl-block"><div class="label">未实现盈亏 (USDT)</div><div class="pnl">+${((position.entry-position.current)*position.qty).toFixed(2)}</div></div><div class="metrics"><div><div class="label">数量 (XRP)</div><div class="value">${qty(position.qty)}</div></div><div><div class="label">入场价格</div><div class="value">${price(position.entry)}</div></div><div><div class="label">当前价格</div><div class="value">${price(position.current)}</div></div></div><div class="protection-line"><span>已确认止损</span><b>${price(position.stop)}</b></div><div class="actions"><button data-act="form" data-id="reduce">减仓</button><button data-act="protection-menu">止盈 / 止损</button><button class="close-action" data-act="form" data-id="close">全平</button></div><div class="context-note">${icon('tighten')}${managementCaption()}</div></article><div class="quiet-space">没有新的判断时，让系统继续管理。</div>`:'<div class="empty">暂无持仓</div>');
 }else if(page==='orders'){
  screen.innerHTML=`<div class="titlebar"><h2>当前委托</h2><button class="help-link" data-act="guide">${icon('help')}操作帮助</button></div>`+(position.qty?`<div class="outcome"><div class="row"><strong>XRPUSDT</strong><span class="tag">系统止损</span></div>${row('触发价',price(position.stop))}${row('保护数量',qty(position.qty)+' XRP')}<button class="secondary" data-act="form" data-id="tighten">收紧止损</button></div>`:'<div class="empty">暂无委托</div>')+(position.qty&&position.tp?`<div class="outcome"><div class="row"><strong>XRPUSDT</strong><span class="tag">人工止盈</span></div>${row('限价',price(position.tp.price))}${row('数量',qty(position.tp.qty)+' XRP')}<button class="secondary" data-act="form" data-id="tp">修改止盈</button><button class="secondary" data-act="form" data-id="cancel">取消人工止盈</button></div>`:'');
 }else{
  screen.innerHTML=`<div class="titlebar"><h2>主控</h2><button class="help-link" data-act="guide">${icon('help')}操作帮助</button></div><div class="control-row row"><div><h3>全局允许新开仓</h3><p>${globalEntry?'已开启':'已暂停'} · 已有持仓继续管理</p></div><button role="switch" aria-checked="${globalEntry}" aria-label="全局允许新开仓" class="switch ${globalEntry?'on':''}" data-act="control" data-id="global"><span></span></button></div><div class="section-label">策略 · 允许新开仓</div>`+Object.entries(strategies).map(([k,on])=>`<div class="control-row row"><div><h3>${k}</h3><p>${!on?'已暂停':!globalEntry?'已启用 · 全局暂停中':'已启用'}</p></div><button role="switch" aria-checked="${on}" aria-label="${k}允许新开仓" class="switch ${on?'on':''}" data-act="control" data-id="${k}"><span></span></button></div>`).join('');
 }
 screen.scrollTop=0;
}
function renderGuide(){closeSheet();view='guide';nav();screen.innerHTML=`<div class="back-title"><button data-act="home" aria-label="返回持仓">${icon('back')}</button><h2>操作帮助</h2></div><div class="guide-head"><h1>这次想怎么调整？</h1><p>先选意图，再看操作后的变化。</p></div><div class="guide-list">`+Object.entries(guides).map(([id,g])=>`<button class="intent" data-act="detail" data-id="${id}"><span class="intent-icon">${icon(g.icon)}</span><span class="intent-text"><strong>${g.title}</strong><small>${g.sub}</small></span><span class="chevron">›</span></button>`).join('')+`</div><div class="guide-footer">${icon('help')}这里只解释操作，不判断买卖时机。</div>`;screen.scrollTop=0;}
function keyNote(id){return {reduce:position.tp?'先处理现有人工止盈，再重新预览减仓。':scenario==='runner'?'已经进入 Runner，减仓后继续原自动追踪。':'减仓不会立即保本；原 TP1 目标仍用于后续转换。',tighten:'只允许收紧。退出更早，也可能错过随后的趋势。',tp:'普通限价单，触价不保证立即或全部成交。',cancel:'不会恢复旧自动 TP1，也不会取消必要止损。',close:'只结束这一笔，不会暂停策略未来的新开仓。',pause:'暂停只影响新开仓，不会平掉已有仓位。'}[id];}
function detailRows(id){switch(id){case'reduce':return row('持仓数量',`${qty(position.qty)} <span class="to">→</span> ${qty(position.qty/2)} XRP`)+row('余仓管理','自动续管')+row('原自动 TP1',scenario==='runner'?'已完成':position.tp?'先处理人工计划':'数量单撤销 · 目标价保留')+`<div class="outcome-bar"><span class="out"></span><span></span></div>`;case'tighten':return row('持仓数量','保持不变')+row('止损边界',`${price(position.stop)} <span class="to">→</span> ${price(scenario==='runner'?1.86:2.04)}`)+row('后续管理','系统仍可进一步收紧');case'tp':return row('原获利计划','替换')+row('新止盈','你指定的价格与数量')+row('余仓管理','按原阶段继续');case'cancel':return row('人工止盈','撤销')+row('当前止损','保留')+row('旧自动 TP1','不恢复');case'close':return row('本笔余仓',`${qty(position.qty)} <span class="to">→</span> 0 XRP`)+row('其他持仓','保持不变')+row('新开仓开关','保持原值');case'pause':return row('新增交易','暂停')+row('已有自动持仓','继续管理')+row('单独暂停策略','也可以');}}
function renderDetail(id){closeSheet();view='detail';selected=id;nav();const g=guides[id];const noPosition=id!=='pause'&&!position.qty;screen.innerHTML=`<div class="back-title"><button data-act="guide" aria-label="返回操作帮助">${icon('back')}</button><h2>操作帮助</h2><small>${id==='pause'?'账户控制':stateName()}</small></div><div class="detail-hero"><div class="detail-icon">${icon(g.icon)}</div><h1>${g.title}</h1><p>${g.lead}</p><span class="operation-chip">对应操作 · ${g.button}</span></div><section class="outcome" aria-label="操作影响"><div class="eyebrow">操作后的变化</div>${detailRows(id)}</section><div class="key-note">${icon('help')}<span>${keyNote(id)}</span></div><details class="example"><summary>用一个例子理解</summary><p>${esc(id==='reduce'&&scenario==='runner'?'已经进入 Runner 时，减仓只缩小参与趋势的数量，系统按实际余仓继续追踪，不重新等待 TP1。':g.example)}</p></details><div class="guide-cta"><div class="target-chip"><span>操作对象</span><b>${id==='pause'?'全局或指定策略':'XRPUSDT · 空'}</b></div><button class="primary" data-act="${id==='pause'?'choose-pause':'form'}" data-id="${id}" ${noPosition?'disabled':''}>${noPosition?'当前没有持仓':'进入'+g.button}</button><div class="small-foot">打开表单后，还需预览和确认。</div></div>`;screen.scrollTop=0;}
function sheetHead(title,subtitle='XRPUSDT · 空'){return `<div class="handle"></div><div class="sheet-top"><h2 id="sheet-title">${title}</h2><button class="x" data-act="dismiss" aria-label="关闭面板">×</button></div><p class="subtitle">${subtitle}</p>`;}
function openSheet(html){lastFocus=document.activeElement;sheet.innerHTML=html;overlay.hidden=false;sheet.scrollTop=0;sheet.focus();}
function closeSheet(){if(submitted)return;overlay.hidden=true;sheet.innerHTML='';lastFocus?.isConnected&&lastFocus.focus?.();}
function contextualHelp(id){return `<button class="context-help" data-act="detail" data-id="${id}">${icon('help')}这项操作会改变什么</button>`;}
function openForm(id){if(submitted)return;selected=id;
 if(!position.qty&&id!=='pause'){toast('当前没有可操作的持仓');return;}
 if(id==='reduce'&&position.tp){openSheet(sheetHead('先处理人工止盈')+`<div class="change-list">${row('现有人工止盈',price(position.tp.price))}${row('待退出数量',qty(position.tp.qty)+' XRP')}</div><p class="result-copy">减仓和独立人工止盈不并行。先修改或取消计划，再核实减仓。</p><button class="primary" data-act="form" data-id="cancel">查看取消人工止盈</button><button class="secondary" data-act="dismiss">暂不调整</button>`);return;}
 if(id==='cancel'&&!position.tp){openSheet(sheetHead('暂无人工止盈')+`<div class="key-note">${icon('help')}<span>只能取消自己设置的止盈，不能在这里取消原自动 TP1。</span></div><button class="primary" data-act="form" data-id="tp">设置人工止盈</button><button class="secondary" data-act="dismiss">返回</button>`);return;}
 const labels={reduce:'市价减仓',tighten:'收紧止损',tp:'限价止盈',cancel:'取消人工止盈',close:'市价全平'};
 const needsQty=['reduce','tp'].includes(id),needsPrice=['tighten','tp'].includes(id);
 let fields='';
 if(needsQty)fields+=`<div class="field"><label for="quantity">${id==='reduce'?'减仓数量':'止盈数量'}</label><div class="input-wrap"><input id="quantity" type="text" inputmode="decimal" autocomplete="off" value="${qty(position.qty*(id==='reduce'?.5:.25))}" required><span>XRP</span></div><div class="chips">${[25,50,75].map(n=>`<button type="button" data-act="percent" data-id="${n}" class="${n===(id==='reduce'?50:25)?'selected':''}">${n}%</button>`).join('')}</div></div>`;
 if(needsPrice)fields+=`<div class="field"><label for="price">${id==='tighten'?'止损触发价':'止盈限价'}</label><div class="input-wrap"><input id="price" type="text" inputmode="decimal" autocomplete="off" value="${price(id==='tighten'?(scenario==='runner'?1.86:2.04):(position.tp?.price||1.84))}" required><span>USDT</span></div></div>`;
 openSheet(sheetHead(labels[id])+contextualHelp(id)+`<form id="operation-form" data-kind="${id}">${fields}<div class="form-summary">${row('当前余仓',qty(position.qty)+' XRP')}${row('当前止损',price(position.stop))}${id==='close'?row('退出范围','本笔全部余仓'):''}${id==='cancel'?row('人工止盈',price(position.tp.price)+' · '+qty(position.tp.qty)+' XRP'):''}</div><div class="form-error" id="form-error" role="alert"></div><button class="primary" type="submit">核实并预览</button></form>`);
}
function choosePause(){openSheet(sheetHead('暂停新开仓','选择作用范围')+`<div class="change-list">${row('已有自动仓位','继续管理')}</div><button class="primary" data-act="control" data-id="global">${globalEntry?'暂停全局新开仓':'全局已暂停 · 查看'}</button>`+Object.entries(strategies).map(([id,on])=>`<button class="secondary" data-act="control" data-id="${id}">${on?'暂停':'查看'} ${id}</button>`).join(''));}
function controlPreview(key){const isGlobal=key==='global',isOn=isGlobal?globalEntry:strategies[key];request={kind:'pause',key,enabled:!isOn};showPreview();}
function previewForm(form){const kind=form.dataset.kind,q=Number($('#quantity')?.value),p=Number($('#price')?.value);let error='';
 if(['reduce','tp'].includes(kind)&&(!Number.isFinite(q)||q<=0||q>position.qty||Math.abs(q*10-Math.round(q*10))>1e-7))error='请输入不超过余仓的有效数量，步长 0.1 XRP。';
 if(kind==='reduce'&&q>=position.qty)error='减仓需要保留余仓；结束这笔交易请使用全平。';
 if(['tighten','tp'].includes(kind)&&(!Number.isFinite(p)||p<=0))error='请输入有效价格。';
 if(kind==='tighten'&&!(position.current<p&&p<position.stop))error='空仓止损需低于原止损，并高于当前价。';
 if(kind==='tp'&&!(p<position.current))error='空仓止盈限价需低于当前价，请重新输入。';
 if(error){$('#form-error').textContent=error;return;}
 request={kind,qty:q,price:p};showPreview();
}
function showPreview(){const r=request,kind=r.kind,title={reduce:'确认市价减仓',tighten:'确认收紧止损',tp:'确认限价止盈',cancel:'确认取消人工止盈',close:'确认本笔全平',pause:r.enabled?'确认恢复新开仓':'确认暂停新开仓'}[kind];let changes='';
 if(kind==='reduce')changes=row('减仓数量',qty(r.qty)+' XRP')+row('剩余仓位',`${qty(position.qty)} <span class="to">→</span> <span class="change">${qty(position.qty-r.qty)} XRP</span>`)+row('当前止损',price(position.stop)+' · 继续保护')+row('原 TP1',scenario==='runner'?'已完成 · 继续 Runner':'数量单撤销 · 目标 1.8800 保留')+row('余仓管理',scenario==='runner'?'继续 Runner':'等待原目标价后的保本 / Runner');
 if(kind==='tighten')changes=row('止损价格',`${price(position.stop)} <span class="to">→</span> <span class="change">${price(r.price)}</span>`)+row('仓位数量',qty(position.qty)+' XRP · 不变')+row('余仓管理','系统继续追踪，可进一步收紧');
 if(kind==='tp')changes=row('止盈限价',`<span class="change">${price(r.price)}</span>`)+row('退出数量',qty(r.qty)+' XRP')+row('原获利计划','替换为此计划')+row('成交方式','普通限价 · GTC')+row('完整成交后',r.qty===position.qty?'全量退出并收尾':'余仓按原阶段继续管理');
 if(kind==='cancel')changes=row('人工止盈',price(position.tp.price)+' · '+qty(position.tp.qty)+' XRP')+row('处理','撤销')+row('当前止损',price(position.stop)+' · 保留')+row('旧自动 TP1','不恢复');
 if(kind==='close')changes=row('退出数量',`<span class="change">${qty(position.qty)} XRP · 全部</span>`)+row('完成后余仓','0 XRP')+row('相关残单','核实成交后清理')+row('新开仓开关','不变');
 if(kind==='pause')changes=row('作用范围',r.key==='global'?'全部策略':esc(r.key))+row('新开仓',r.enabled?'恢复允许':'暂停')+row('已有持仓','继续管理');
 const note=['reduce','close'].includes(kind)?'市价成交价以实际结果为准。':kind==='tp'?'触价可能部分成交，不保证立即全部成交。':kind==='tighten'?'保护确认后生效，当前保护不会先被撤空。':kind==='cancel'?'原失败 / 时间退出规则仍然有效。':'恢复允许不等于一定产生订单。';
 openSheet(sheetHead(title,kind==='pause'?'新开仓控制':'XRPUSDT · 空')+`<div class="change-list">${changes}</div><div class="key-note">${icon('help')}<span>${note}</span></div><button class="primary ${kind==='close'?'danger-primary':''}" data-act="submit">确认提交 · 模拟</button><button class="secondary" data-act="${kind==='pause'?'choose-pause':'form'}" data-id="${kind}">返回修改</button><p class="small-foot">所有变化仅作用于本地演示。</p>`);
}
function submit(){if(submitted||!request)return;submitted=true;const r={...request};sheet.innerHTML=sheetHead('已受理 · 核实中')+`<div class="spinner"></div><p class="result-copy">模拟后台执行，正在确认实际结果。</p><p class="result-foot">受理不等于完成。</p>`;setTimeout(()=>{
 let title='操作已完成',copy='';
 if(r.kind==='reduce'){position.qty-=r.qty;position.profit='condition';title='减仓已完成';copy=`已减仓 ${qty(r.qty)} XRP，剩余 ${qty(position.qty)} XRP。${scenario==='runner'?'继续原 Runner 追踪。':'保留原目标价条件，余仓继续自动管理。'}`;}
 if(r.kind==='tighten'){position.stop=r.price;title='新止损已确认';copy=`已确认止损 ${price(r.price)}，仓位数量不变。系统继续自动管理。`;}
 if(r.kind==='tp'){position.profit='manual';position.tp={price:r.price,qty:r.qty};title='人工止盈已挂出';copy=`${price(r.price)} · ${qty(r.qty)} XRP 的限价单已挂出，尚未成交。${scenario==='runner'?'原 Runner 仍继续追踪。':'原失败 / 时间退出仍然有效。'}`;}
 if(r.kind==='cancel'){position.tp=null;position.profit='cancelled';title='人工止盈已取消';copy='当前止损保留，旧自动 TP1 未恢复。';}
 if(r.kind==='close'){position.qty=0;position.tp=null;title='本笔已平仓';copy='本笔余仓与残单已在演示中收尾。策略和全局新开仓开关未改变。';}
 if(r.kind==='pause'){if(r.key==='global')globalEntry=r.enabled;else strategies[r.key]=r.enabled;title=r.enabled?'新开仓已恢复允许':'新开仓已暂停';copy='已有持仓仍继续自动管理，交易是否发生仍由策略与全部准入条件决定。';}
 submitted=false;sheet.innerHTML=sheetHead('操作结果',r.kind==='pause'?'新开仓控制':'XRPUSDT · 空')+`<div class="success-icon">${icon('check')}</div><h3 class="result-title">${title}</h3><p class="result-copy">${copy}</p><p class="result-foot">模拟结果 · 未发送真实交易</p><button class="primary" data-act="result-home">${r.kind==='pause'?'返回主控':'返回持仓'}</button>`;renderBackground();
 },650);}
function renderBackground(){const saved=view;if(saved==='detail')return;renderHome();}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3200);}
function switchScenario(id){if(submitted)return;scenario=id;resetState();document.querySelectorAll('[data-act="scenario"]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.id===id)));const last=view,guide=selected;closeSheet();if(last==='detail')renderDetail(guide);else if(last==='guide')renderGuide();else renderHome();}
function demoSettings(){openSheet(sheetHead('原型演示','切换持仓阶段，查看不同帮助')+`<div class="scenario">${[['before','TP1 前'],['runner','Runner 中'],['manual','人工止盈中']].map(([k,v])=>`<button data-act="scenario" data-id="${k}" aria-pressed="${scenario===k}">${v}</button>`).join('')}</div><button class="secondary" data-act="reset">重置演示</button>`);}
function protectionMenu(){openSheet(sheetHead('止盈 / 止损')+`<button class="primary" data-act="form" data-id="tighten">收紧止损</button><button class="secondary" data-act="form" data-id="tp">设置 / 修改止盈</button><button class="secondary" data-act="form" data-id="cancel" ${!position.tp?'disabled':''}>取消人工止盈</button><button class="context-help" data-act="guide">${icon('help')}按意图查看操作帮助</button>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled||submitted)return;const {act,id}=b.dataset;
 if(act==='home'){page='positions';closeSheet();renderHome();}
 if(act==='nav'){page=id;closeSheet();renderHome();}
 if(act==='guide')renderGuide();if(act==='detail')renderDetail(id);if(act==='form')openForm(id);
 if(act==='dismiss')closeSheet();if(act==='choose-pause')choosePause();if(act==='control')controlPreview(id);if(act==='submit')submit();
 if(act==='percent'){const field=$('#quantity');if(field){field.value=position.qty*Number(id)/100;document.querySelectorAll('[data-act="percent"]').forEach(x=>x.classList.toggle('selected',x===b));}}
 if(act==='scenario')switchScenario(id);if(act==='demo-settings')demoSettings();if(act==='protection-menu')protectionMenu();
 if(act==='reset'){scenario='before';switchScenario('before');page='positions';renderHome();toast('演示已重置');}
 if(act==='result-home'){page=request?.kind==='pause'?'control':'positions';closeSheet();renderHome();}
});
document.addEventListener('submit',e=>{if(e.target.id==='operation-form'){e.preventDefault();previewForm(e.target);}});
overlay.addEventListener('click',e=>{if(e.target===overlay)closeSheet();});
document.addEventListener('keydown',e=>{if(overlay.hidden)return;if(e.key==='Escape'){e.preventDefault();closeSheet();}if(e.key==='Tab'){const items=Array.from(sheet.querySelectorAll('button:not(:disabled),input,summary,[tabindex="0"]'));if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===sheet)){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===sheet)){e.preventDefault();first.focus();}}});
resetState();renderHome();
